const cfg = $('Config — AI Visibility').first().json;
const master = $('Read Master_Briefs').all().map(i => i.json || {});
const daily = $('Read Daily_Monitor').all().map(i => i.json || {});

const clean = v => String(v ?? '').trim();
const norm = v => clean(v).toLowerCase().replace(/ё/g,'е').replace(/[–—]/g,'-').replace(/\s+/g,' ');
const yes = v => v === true || /^(1|true|yes|y|да|on)$/i.test(clean(v));
const slugFromUrl = u => clean(u).replace(/\/$/, '').split('/').pop();
const pick = (...vals) => vals.map(clean).find(Boolean) || '';

const dBySlug = new Map();
for (const d of daily) {
  if (clean(d.type) !== 'target' || !yes(d.active)) continue;
  dBySlug.set(slugFromUrl(d.url), d);
}

const candidates = master.filter(m => clean(m.slug) && clean(m.primary_query) && clean(m.category));
if (!candidates.length) throw new Error('Master_Briefs: нет строк с slug + category + primary_query');

// Production allow-list: if at least one row has ai_monitor=YES,
// only those rows are part of FULL. Otherwise use all valid rows.
const marked = candidates.filter(m => yes(m.ai_monitor));
const pool = marked.length ? marked : candidates;

// De-duplicate by slug, keep Master_Briefs order.
const unique = [];
const seen = new Set();
for (const m of pool) {
  const slug = clean(m.slug);
  if (!slug || seen.has(slug)) continue;
  seen.add(slug);
  unique.push(m);
}

const hardCap = Number(cfg.MAX_PRIMARY_COUNT || 20);
if (unique.length > hardCap) {
  throw new Error(`FULL safety stop: найдено ${unique.length} категорий, hard cap = ${hardCap}. Платные AI-запросы НЕ запущены.`);
}

// Keep core generic query first when present; then all remaining categories.
// Branded control is allowed and simply excluded from non-branded visibility denominator.
const preferred = unique.find(m => norm(m.primary_query) === 'перкуссионный массажер');
const rows = preferred
  ? [preferred, ...unique.filter(m => m !== preferred)]
  : unique;

const runId = cfg.RUN_ID || new Date().toISOString();
return rows.map((m, idx) => {
  const slug = clean(m.slug);
  const d = dBySlug.get(slug) || {};
  const query = clean(m.primary_query);
  const brandedControl = /\bbooster\b/i.test(query);
  const expectedNames = pick(m.expected_names, d.expected_names);
  const names = expectedNames.split(',').map(s => s.trim()).filter(Boolean);
  const boosterModels = names.filter(n => /\bbooster\b/i.test(n));
  const ownerUrl = pick(m.owner_url, m.url, d.url, `https://boosterpro.ru/collection/${slug}`);
  const prompt = `Пользователь из России ищет: «${query}». Назови до 5 конкретных брендов или моделей, которые ты бы рекомендовал сейчас. Только список названий, без объяснений. Не ограничивайся одним брендом.`;

  return {json:{
    run_id: runId,
    run_mode: cfg.RUN_MODE,
    run_source: cfg.RUN_SOURCE,
    query_index: idx + 1,
    slug,
    page_id: clean(m.page_id),
    category: clean(m.category),
    query,
    owner_url: ownerUrl,
    expected_h1: pick(m.h1, m.H1, m.expected_h1, d.expected_h1),
    expected_title: pick(m.title, m.Title, m.expected_title, d.expected_title),
    expected_desc: pick(m.description, m.meta_description, m.desc, m.expected_desc, d.expected_desc),
    expected_names: expectedNames,
    booster_models: boosterModels,
    score_eligible: brandedControl ? 'no' : 'yes',
    brand_control: brandedControl ? 'yes' : 'no',
    prompt
  }};
});

let base = $('Build AI Visibility Queries').all().map(i => i.json);
const cfg = $('Config — AI Visibility').first().json;
// FULL safety cap: query builder has already validated <= MAX_PRIMARY_COUNT.
const cap = Math.max(1, Number(cfg.MAX_PRIMARY_COUNT || 20));
base = base.slice(0, cap);
return base.map(x => {
  const requestBody = {
    messages: [{ content: x.prompt, role: 'ROLE_USER' }],
    folderId: cfg.YANDEX_FOLDER_ID,
    fixMisspell: true,
    enableRichStructuredAnswer: true,
    getPartialResults: false
  };
  return {json:{
    ...x,
    provider:'yandex',
    provider_label:'Яндекс / GenSearch',
    model:'yandex-gensearch',
    request_body: JSON.stringify(requestBody)
  }};
});

const tasks = $('Prepare Yandex Tasks').all().map(i => i.json);
const res = $('Yandex GenSearch').all().map(i => i.json || {});
const domain = String($('Config — AI Visibility').first().json.DOMAIN || 'boosterpro.ru').toLowerCase();
const uniq = a => [...new Set(a.filter(Boolean))];
const escText = x => String(x ?? '');
return tasks.map((t, idx) => {
  let r = res[idx] || {};
  if (r.body && typeof r.body === 'object') r = r.body;

  // Successful GenSearch response: message is an object with message.content.
  const text = escText(r?.message?.content || r?.content || r?.answer || '');
  const sources = Array.isArray(r?.sources) ? r.sources : [];
  const allSourceUrls = uniq(sources.map(s => escText(s?.url)));
  const usedSourceUrls = uniq(sources.filter(s => s?.used === true).map(s => escText(s?.url)));
  const textUrls = text.match(/https?:\/\/[^\s)\]}>]+/g) || [];
  const urls = uniq([...usedSourceUrls, ...textUrls]);

  const brandMentioned = /\bbooster\b/i.test(text);
  const models = (t.booster_models || []).filter(m => text.toLowerCase().includes(String(m).toLowerCase()));

  // 'site_cited' means Yandex actually USED boosterpro.ru as a source, not merely found it in candidates.
  const siteCited = usedSourceUrls.some(u => u.toLowerCase().includes(domain)) || new RegExp(domain.replace('.', '\\.'), 'i').test(text);
  const siteFoundCandidate = allSourceUrls.some(u => u.toLowerCase().includes(domain));

  // API errors have numeric code and string message. A successful response has message as an object.
  const code = r?.code ?? r?.error?.code ?? '';
  const apiMsg = typeof r?.message === 'string'
    ? r.message
    : (typeof r?.error?.message === 'string' ? r.error.message : '');
  const rejected = r?.isAnswerRejected === true || r?.problematicAnswer === true;
  let errorText = '';
  if (code || apiMsg) errorText = `${code ? 'code='+code+'; ' : ''}${apiMsg || 'api_error'}`;
  else if (rejected) errorText = 'answer_rejected_or_problematic';
  else if (!text) errorText = 'empty_response';

  return {json:{...t,
    checked_at:new Date().toISOString(),
    provider_disabled:false,
    brand_mentioned:brandMentioned,
    site_cited:siteCited,
    site_found_candidate:siteFoundCandidate,
    models_mentioned:models.join(', '),
    source_urls:urls.join('\n'),
    source_urls_all:allSourceUrls.join('\n'),
    answer_text:text.slice(0,45000),
    api_cost:0,
    web_search_requests:1,
    data_error:!!errorText,
    error:errorText.slice(0,1000)
  }};
});

