const hash = s => {
  let h = 2166136261;
  for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16);
};
return all.map(r => ({json:{...r,
  state_key:`${String(r.run_mode || 'FULL')}|${r.provider}|${r.slug}`,
  history_key:`${String(r.run_mode || 'FULL')}|${r.run_id}|${r.provider}|${r.slug}`,
  state_hash:hash(`${r.brand_mentioned}|${r.site_cited}|${r.models_mentioned}|${r.answer_text}`)
}}));

