  .map(i => i.json || {})
  .filter(x => x.provider && x.slug && String(x.state_key || '').startsWith(`${runMode}|`));
const providers = [['yandex','Яндекс'],['gpt','GPT'],['gemini','Gemini'],['qwen','Qwen']];
const baseRows = $('Build AI Visibility Queries').all().map(i => i.json || {});
const eligibleSlugs = [...new Set(results.filter(r => r.score_eligible === 'yes').map(r => String(r.slug || '')))];
const eligibleSet = new Set(eligibleSlugs);
const totalEligible = eligibleSlugs.length;
const MIN_COVERAGE = Number(cfg.MIN_COVERAGE || 0.80);
const isErr = r => !r || r.data_error === true || String(r.data_error).toLowerCase()==='true';
const isTrue = v => v === true || String(v).toLowerCase()==='true';
const pct = (n,d) => d ? Math.round(n/d*100) : null;
const pp = (a,b) => (Number.isFinite(a) && Number.isFinite(b)) ? a-b : null;
const deltaTxt = d => d === null ? '—' : d > 0 ? `(Δ +${d} п.п.) 🔼` : d < 0 ? `(Δ -${Math.abs(d)} п.п.) 🔻` : `(Δ 0 п.п.) ➖`;
// Graphviz/PNG: only plain text glyphs. Direction is shown by font color,
// so QuickChart cannot render emoji/tofu squares here.
const deltaTxtChart = d => d === null ? '—' : d > 0 ? `+${d} п.п.` : d < 0 ? `-${Math.abs(d)} п.п.` : `0 п.п.`;
const deltaColorChart = d => d === null ? '#b9c4d0' : d > 0 ? '#73d89d' : d < 0 ? '#ff8f98' : '#b9c4d0';
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

// ---------- Реально использованные/процитированные источники ----------
const providerLabels = {yandex:'Яндекс',gpt:'GPT',gemini:'Gemini',qwen:'Qwen'};
const domainOf = u => {
  const s = String(u || '').trim();
  const m = s.match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].replace(/^www\./i,'').toLowerCase() : '';
};
const buildSourceStats = rows => {
  const map = new Map();
  for (const r of rows) {
    const p = String(r.provider || '').toLowerCase();
    if (!providerLabels[p] || isErr(r)) continue;
    if (!eligibleSet.has(String(r.slug || ''))) continue;
    const urls = String(r.source_urls || '').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
    const domains = [...new Set(urls.map(domainOf).filter(Boolean))];
    for (const domain of domains) {
      if (!map.has(domain)) map.set(domain,{domain,uses:0,yandex:0,gpt:0,gemini:0,qwen:0,providers:new Set(),answers:new Set()});
      const s=map.get(domain);
      const answerKey=`${p}|${String(r.slug || '')}`;
      if (!s.answers.has(answerKey)) {
        s.answers.add(answerKey);
        s.uses++;
        s[p]++;
        s.providers.add(providerLabels[p]);
      }
    }
  }
  let arr=[...map.values()].map(s=>({domain:s.domain,uses:s.uses,yandex:s.yandex,gpt:s.gpt,gemini:s.gemini,qwen:s.qwen,providers:[...s.providers]}))
    .sort((a,b)=>b.uses-a.uses || a.domain.localeCompare(b.domain));
  const total=arr.reduce((sum,s)=>sum+Number(s.uses||0),0);
  arr=arr.map(s=>({...s,pct:total ? Math.round((Number(s.uses||0)/total)*1000)/10 : 0}));
  return {arr,total};
};
const currentSources=buildSourceStats(results);
let sourceStats=currentSources.arr;
const totalSourceUses=currentSources.total;
const previousSources=buildSourceStats(prevRaw);

// Source dynamics are valid only when the previous State covers the SAME
// current slug set for every active provider. This prevents DEV1 -> DEV4
// from being shown as fake +7 / +3 growth.
const hasComparableSourceBaseline = totalEligible > 0 && providers.every(([p]) => {
  const prev = prevRaw.filter(r =>
    r.provider===p &&
    eligibleSet.has(String(r.slug || '')) &&
    String(r.score_eligible)==='yes' &&
    !isErr(r)
  );
  return (prev.length / totalEligible) >= MIN_COVERAGE;
});

const prevSourceMap=new Map(previousSources.arr.map(s=>[s.domain,s]));
sourceStats=sourceStats.map(s=>({
  ...s,
  delta_uses:hasComparableSourceBaseline
    ? Number(s.uses||0)-Number(prevSourceMap.get(s.domain)?.uses||0)
    : null
}));
const boosterSourceUses = sourceStats.find(s=>s.domain==='boosterpro.ru')?.uses || 0;
const boosterSourcePct = totalSourceUses ? Math.round((boosterSourceUses/totalSourceUses)*1000)/10 : 0;

// ---------- Метрики по AI + динамика по тем же slug ----------
const stats = {};
for (const [p,label] of providers) {
  const providerRows = results.filter(r => r.provider===p);
  const disabled = providerRows.length > 0 && providerRows.every(r => r.provider_disabled === true || String(r.provider_disabled).toLowerCase()==='true');
  const curAll = providerRows.filter(r => r.score_eligible==='yes' && eligibleSet.has(String(r.slug || '')));
  const cur = curAll.filter(r => !isErr(r));
  const errors = curAll.length-cur.length;
  const coverage = totalEligible ? cur.length/totalEligible : 0;
  const publishable = coverage >= MIN_COVERAGE;
  const brand = cur.filter(r => isTrue(r.brand_mentioned)).length;
  const cited = cur.filter(r => isTrue(r.site_cited)).length;
  const rawBrandPct = pct(brand,cur.length);
  const rawCitedPct = pct(cited,cur.length);
  const brandPct = publishable ? rawBrandPct : null;
  const citedPct = publishable ? rawCitedPct : null;

  const prev = prevRaw.filter(r => r.provider===p && eligibleSet.has(String(r.slug || '')) && String(r.score_eligible)==='yes' && !isErr(r));
  const prevCoverage = totalEligible ? prev.length/totalEligible : 0;
  const hasPrevious = prevCoverage >= MIN_COVERAGE;
  let prevBrandPct=null, prevCitedPct=null;
  if (hasPrevious) {
    prevBrandPct=pct(prev.filter(r=>isTrue(r.brand_mentioned)).length,prev.length);
    prevCitedPct=pct(prev.filter(r=>isTrue(r.site_cited)).length,prev.length);
  }
  stats[p]={label,disabled,total:totalEligible,valid:cur.length,errors,coverage:Math.round(coverage*100),publishable,
    brand,cited,brandPct,citedPct,rawBrandPct,rawCitedPct,hasPrevious,prevBrandPct,prevCitedPct,
    dBrand:hasPrevious?pp(brandPct,prevBrandPct):null,dCited:hasPrevious?pp(citedPct,prevCitedPct):null};
}

const providerCosts = Object.fromEntries(providers.map(([p]) => [p, results.filter(r=>r.provider===p).reduce((s,r)=>s+Number(r.api_cost||0),0)]));
const openRouterCost = providerCosts.gpt + providerCosts.gemini + providerCosts.qwen;
const yandexSuccessful = results.filter(r=>r.provider==='yandex' && !isErr(r)).length;
const yandexEstRub = yandexSuccessful * Number(cfg.YANDEX_RUB_PER_REQUEST || 5.08);
const now = new Date(results[0]?.checked_at || Date.now());
const date = now.toISOString().slice(0,10);

// ---------- Telegram: результат → динамика → источники ----------
let summary = `<b>🤖 AI Visibility · ${date}</b>\n`;
for (const [p,label] of providers) {
  const s=stats[p];
  if (s.disabled) { summary += `<b>${label}</b>: отключено\n`; continue; }
  if (!s.publishable) { summary += `<b>${label}</b>: недостаточно данных · ${s.valid}/${s.total} · ошибок ${s.errors}\n`; continue; }
  summary += `<b>${label}</b>: Booster <b>${s.brand}/${s.valid} (${s.brandPct}%)</b> · Упоминание Boosterpro.ru <b>${s.cited}/${s.valid} (${s.citedPct}%)</b>`;
  if (s.errors) summary += ` · ошибок ${s.errors}`;
  summary += `\n`;
}
const prevProviders=providers.filter(([p])=>stats[p]?.hasPrevious);
summary += `\n📈 <b>Динамика к прошлому сохранённому срезу</b>\n`;
if (!prevProviders.length) {
  summary += `— сравнимого прошлого среза пока нет\n`;
} else {
  for (const [p,label] of prevProviders) {
    const s=stats[p];
    summary += `<b>${label}</b>: Booster ${deltaTxt(s.dBrand)} · Boosterpro.ru ${deltaTxt(s.dCited)}\n`;
  }
}

summary += `\n🌐 <b>Использованные источники</b> · ${totalSourceUses} использований\n`;
if (!sourceStats.length) {
  summary += `— источников нет\n`;
} else {
  const maxTelegramSources=10;
  const boosterTg=sourceStats.find(s=>s.domain==='boosterpro.ru' && Number(s.uses||0)>0);
  let telegramSources=sourceStats.slice(0,maxTelegramSources);
  if (boosterTg && !telegramSources.some(s=>s.domain==='boosterpro.ru')) {
    telegramSources=[...sourceStats.filter(s=>s.domain!=='boosterpro.ru').slice(0,maxTelegramSources-1),boosterTg];
  }
  telegramSources.forEach((s,i)=>{
    const who=(s.providers||[]).join(', ')||'—';
    const delta=s.delta_uses===null||s.delta_uses===undefined?'':s.delta_uses>0?` · (Δ +${s.delta_uses}) 🔼`:s.delta_uses<0?` · (Δ -${Math.abs(s.delta_uses)}) 🔻`:` · (Δ 0) ➖`;
    const line=`${i+1}. ${esc(s.domain)} — ${Number(s.pct||0).toFixed(1)}% · ${s.uses} · ${esc(who)}${delta}`;
    summary += s.domain==='boosterpro.ru' ? `<b>${line}</b>\n` : `${line}\n`;
  });
  const hiddenCount=Math.max(0,sourceStats.length-telegramSources.length);
  if (hiddenCount) summary += `… ещё ${hiddenCount} источников — в полном отчёте\n`;
}

// ---------- Матрица ----------
const cell = r => {
  if (r && (r.provider_disabled === true || String(r.provider_disabled).toLowerCase()==='true')) return ['отключено','#343b46','#b8c0cc'];
  if (!r || isErr(r)) return ['ошибка','#6a3a17','#ffd6a3'];
  const b=isTrue(r.brand_mentioned), c=isTrue(r.site_cited);
  if (b&&c) return ['Booster + источник','#24543a','#d8f5df'];
  if (b) return ['Booster','#655819','#fff0a8'];
  if (c) return ['источник','#244b70','#d8ecff'];
  return ['—','#5a2e35','#ffd7dc'];
};
let rows='';
for (const q of baseRows) {
  rows += `<TR>`;
  rows += `<TD WIDTH="315" ALIGN="LEFT" BALIGN="LEFT" BGCOLOR="#242c38"><TABLE WIDTH="315" BORDER="0" CELLBORDER="0" CELLSPACING="0" CELLPADDING="0"><TR><TD ALIGN="LEFT"><FONT COLOR="#f3f5f7"><B>${esc(q.category)}</B></FONT></TD></TR><TR><TD ALIGN="LEFT"><FONT POINT-SIZE="9" COLOR="#9ca8b8">${esc(q.query)}</FONT></TD></TR></TABLE></TD>`;
  for (const [p] of providers) {
    const r=results.find(x=>x.provider===p && x.slug===q.slug);
    const [txt,bg,fg]=cell(r);
    rows += `<TD WIDTH="270" ALIGN="LEFT" BALIGN="LEFT" BGCOLOR="${bg}"><FONT COLOR="${fg}"><B>${txt}</B></FONT></TD>`;
  }
  rows += `</TR>`;
}
const matrixDot = `digraph G { graph [bgcolor="#151a22", pad="0.22"]; node [shape=plain fontname="DejaVu Sans"]; M [label=<
<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="0" CELLPADDING="8" COLOR="#414b59" BGCOLOR="#202733">
<TR><TD COLSPAN="5" ALIGN="CENTER" BGCOLOR="#151a22"><FONT COLOR="#f3f5f7" POINT-SIZE="19"><B>AI Visibility · Booster</B></FONT></TD></TR>
<TR><TD WIDTH="315" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>КАТЕГОРИЯ / ЗАПРОС</B></FONT></TD><TD WIDTH="270" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>ЯНДЕКС</B></FONT></TD><TD WIDTH="270" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>GPT</B></FONT></TD><TD WIDTH="270" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>GEMINI</B></FONT></TD><TD WIDTH="270" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>QWEN</B></FONT></TD></TR>
${rows}
</TABLE>>]; }`;

// ---------- Шкалы: <20 красный, 20–64 жёлтый, 65+ зелёный ----------
const scoreColor = v => {
  if (!Number.isFinite(v)) return '#3a4350';
  if (v < 20) return '#a33a3f';
  if (v < 65) return '#b58a19';
  return '#2f7a4d';
};
const barCell = v => {
  if (!Number.isFinite(v)) return `<TABLE BORDER="0" CELLBORDER="0" CELLSPACING="0"><TR><TD WIDTH="600" ALIGN="LEFT" BGCOLOR="#3a4350"><FONT COLOR="#d7dee8"><B>нет данных</B></FONT></TD></TR></TABLE>`;
  const totalW=600;
  const w=Math.max(1,Math.round(v/100*totalW));
  const rest=Math.max(1,totalW-w);
  return `<TABLE BORDER="0" CELLBORDER="0" CELLSPACING="0"><TR><TD WIDTH="${w}" ALIGN="LEFT" BGCOLOR="${scoreColor(v)}"><FONT COLOR="#ffffff"><B>${v}%</B></FONT></TD><TD WIDTH="${rest}" BGCOLOR="#303946"></TD></TR></TABLE>`;
};
let bars='';
for (const [p,label] of providers) {
  const s=stats[p];
  const coverage=`${s.valid}/${s.total}`;
  bars += `<TR>`;
  bars += `<TD WIDTH="350" ALIGN="LEFT" BGCOLOR="#222b36"><TABLE BORDER="0" CELLBORDER="0" CELLSPACING="0" CELLPADDING="6"><TR><TD ALIGN="LEFT" BGCOLOR="#242c38"><FONT COLOR="#f3f5f7"><B>${label}</B></FONT><BR ALIGN="LEFT"/><FONT POINT-SIZE="9" COLOR="#9ca8b8">данные ${coverage}</FONT></TD></TR><TR><TD ALIGN="LEFT" BGCOLOR="#1d2530"><FONT COLOR="#d9e2ee" POINT-SIZE="10">↳ Упоминание Boosterpro.ru</FONT></TD></TR></TABLE></TD>`;
  bars += `<TD WIDTH="680" ALIGN="LEFT" BGCOLOR="#202733"><TABLE BORDER="0" CELLBORDER="0" CELLSPACING="0" CELLPADDING="6"><TR><TD ALIGN="LEFT">${barCell(s.brandPct)}</TD></TR><TR><TD ALIGN="LEFT">${barCell(s.citedPct)}</TD></TR></TABLE></TD>`;
  bars += `<TD WIDTH="180" ALIGN="LEFT" BGCOLOR="#202733"><TABLE BORDER="0" CELLBORDER="0" CELLSPACING="0" CELLPADDING="11"><TR><TD ALIGN="LEFT"><FONT COLOR="${deltaColorChart(s.dBrand)}">${deltaTxtChart(s.dBrand)}</FONT></TD></TR><TR><TD ALIGN="LEFT"><FONT COLOR="${deltaColorChart(s.dCited)}">${deltaTxtChart(s.dCited)}</FONT></TD></TR></TABLE></TD>`;
  bars += `</TR>`;
}
const barsDot = `digraph G { graph [bgcolor="#151a22", pad="0.25"]; node [shape=plain fontname="DejaVu Sans"]; B [label=<
<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="0" CELLPADDING="7" COLOR="#414b59" BGCOLOR="#202733">
