<TR><TD WIDTH="350" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>AI</B></FONT></TD><TD WIDTH="680" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>ВИДИМОСТЬ</B></FONT></TD><TD WIDTH="180" ALIGN="LEFT" BGCOLOR="#2a3340"><FONT COLOR="#f0f3f7"><B>Δ</B></FONT></TD></TR>
${bars}
</TABLE>>]; }`;

// ---------- Donut источников: без фиктивного нулевого сектора ----------
const sourceChartMax = 9;

const boosterReal = sourceStats.find(s=>s.domain==='boosterpro.ru') || {
  domain:'boosterpro.ru', uses:0, pct:0, yandex:0, gpt:0, gemini:0, qwen:0,
  providers:[], delta_uses:0
};

// В круг попадают только реально использованные домены.
// Если boosterpro.ru = 0, отдельного нулевого сектора/маркера НЕТ.
// Сам boosterpro.ru всегда показываем жирным акцентом в центре.
const positiveSources=sourceStats.filter(s=>Number(s.uses||0)>0);
let pieItems=positiveSources.slice(0,sourceChartMax);

// boosterpro.ru must NEVER disappear into "Другие" when it has real uses.
// If it is below top-N, reserve the last explicit slot for it.
if (Number(boosterReal.uses||0)>0 && !pieItems.some(s=>s.domain==='boosterpro.ru')) {
  pieItems=[
    ...positiveSources.filter(s=>s.domain!=='boosterpro.ru').slice(0,sourceChartMax-1),
    boosterReal
  ];
}

const shownDomains = new Set(pieItems.map(s=>s.domain));
const pieTail = positiveSources.filter(s=>!shownDomains.has(s.domain));
if (pieTail.length) {
  const otherUses = pieTail.reduce((sum,s)=>sum+Number(s.uses||0),0);
  const otherPct = totalSourceUses ? Math.round((otherUses/totalSourceUses)*1000)/10 : 0;
  pieItems.push({domain:`Другие (${pieTail.length})`,uses:otherUses,pct:otherPct,providers:[]});
}

const normalPalette=['#4F8FF7','#F05D68','#55C2C3','#66B75A','#F2C94C','#9B6BD3','#FF7FA2','#9C755F','#6C8EBF'];
let paletteIndex=0;
const pieColors=pieItems.map(s=>{
  if (String(s.domain||'').startsWith('Другие (')) return '#6F7B8B';
  return normalPalette[(paletteIndex++)%normalPalette.length];
});
const borderColors=pieItems.map(()=> '#0f141d');
const borderWidths=pieItems.map(()=> 7);

const pieLabels=pieItems.map(s=>{
  const who=(s.providers||[]).length ? ` · ${(s.providers||[]).join(', ')}` : '';
  const domainLabel = s.domain==='boosterpro.ru' ? 'BOOSTERPRO.RU' : s.domain;
  return `${domainLabel} — ${Number(s.pct||0).toFixed(1)}% · ${s.uses} исп.${who}`;
});
const pieData=pieItems.map(s=>Number(s.uses||0));

const labelsJs=JSON.stringify(pieLabels);
const dataJs=JSON.stringify(pieData);
const colorsJs=JSON.stringify(pieColors);
const borderColorsJs=JSON.stringify(borderColors);
const borderWidthsJs=JSON.stringify(borderWidths);
