const cfg = $('Config — AI Visibility').first().json;
const wanted = String(cfg.DRIVE_FOLDER_NAME || 'AI_Visibility_Reports').trim();
const rows = $input.all().map(i => i.json || {}).filter(x => x && x.id);

const clean = s => String(s || '').trim();

// n8n/Drive search can occasionally surface a duplicated display name such as
// AI_Visibility_ReportsAI_Visibility_Reports.
// Prefer exact name, then accept a pure repetition of the configured folder name.
const exact = rows.find(r => clean(r.name) === wanted);

const repeated = rows.find(r => {
  const name = clean(r.name);
  if (!name || !wanted || name.length % wanted.length !== 0) return false;
  const count = name.length / wanted.length;
  return count >= 2 && wanted.repeat(count) === name;
});

const chosen = exact || repeated;

if (!chosen?.id) {
  const found = rows.map(r => clean(r.name)).filter(Boolean).join(', ');
  throw new Error(`Google Drive: папка "${wanted}" не найдена. Найдено: ${found || 'ничего'}.`);
}

return [{json:{
  report_folder_id: chosen.id,
  report_folder_name: clean(chosen.name),
  report_folder_url: chosen.webViewLink || '',
  folder_name_normalized: clean(chosen.name) !== wanted
}}];

// Folder lookup is only for the archive branch.
// Collapse HTML + RAW input to one trigger item so Google Drive search runs once.
return [{json:{archive_ready:true}}];

const rows = $('Build HTML + RAW Archive').all();
